'use strict';

// MCP-2a: a Marrow hold never freezes an agent session. Claude Code auto mode never gets an "ask" (a dialog with no time
// limit that nobody answers); default and acceptEdits ask only when the owner typed in this session in the last 10
// minutes (the UserPromptSubmit hook's marker); everything else answers exactly as master (990aaaa6, published 3.9.109).
// Rows: M2-1 .. M2-9 and M0 .. M6 of ACCEPTANCE bld-mcp2a. Dummy keys are generated by the harness at run time.
const assert = require('node:assert/strict');
const test = require('node:test');
const { chmodSync, existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, renameSync, rmSync, symlinkSync, unlinkSync, writeFileSync } = require('node:fs');
const { tmpdir } = require('node:os');
const { basename, join } = require('node:path');
const { fixture, hostRuntime, ownerLockedRuntime, keyedHarness } = require('./support/first-hour-harness.cjs');
const { buildTable, CLAUDE_VARIANTS, holdRuntimes } = require('./support/hold-plan-table.cjs');

const { ATTENDED_WINDOW_MS, attendedWithin, recordAttendedPrompt } = require('../dist/attended-marker.js');
const { CONTROL_ROUTE_DENY_TEXT } = require('../dist/control-routes.js');
const { HELD_OFFLINE_TEXT, HELD_SLOW_TEXT, MARROW_OUTAGE_WARNING, ownerApprovalPrompt, classifyTool } = require('../dist/hook-pre-action.js');
const { heldNoFreezeText, planHeldAction } = require('../dist/host-approval.js');
const { ordinaryApprovalGuidance, normalizeRuntimeResult } = require('../dist/runtime-contract.js');

const DEPLOY = fixture('claude-pre-tool-use.json');
const PERMISSION_REQUEST = fixture('claude-permission-request.json');
const ev = (over = {}) => ({ ...DEPLOY, ...over });
const decisionOf = (out) => out.json?.hookSpecificOutput?.permissionDecision;
const reasonOf = (out) => out.json?.hookSpecificOutput?.permissionDecisionReason;
const M0_TEXT = (receipt) => `Held for the owner's approval (receipt ${receipt}). Continue other work; run this exact action again after the owner approves.`;
const DIALOG_TEXT = 'Marrow holds this action for your approval. Approve only if you authorize this exact action; Marrow records your answer. Reason: Production deploys need approval.';
const LEGACY_ASK_TEXT = 'Marrow requires owner review before this action. Approve only if you authorize this exact action. Reason: Production deploys need approval.';
const runtimeCalls = (h) => h.requests().filter((r) => r.path === '/v1/agent/runtime');
const withHarness = (fn) => { const h = keyedHarness(); try { return fn(h); } finally { h.cleanup(); } };
const legacyRuntime = (receipt = 'gate-legacy') => {
  const runtime = hostRuntime(receipt);
  for (const field of ['host_approval_endpoint', 'host_approval_accepted', 'host_approval_trust', 'approval_categories', 'verified_approval_required', 'verified_approval_categories']) delete runtime.completion_contract.owner_approval[field];
  runtime.completion_contract.owner_approval.approval_authority = 'authenticated_dashboard_owner';
  return runtime;
};
const E2 = `python3 -I -c 'import json; d=json.load(open("board.json")); print([j["id"] for j in d["jobs"] if any(w in j["id"] for w in ("control","install","update"))])'`;
const dummyKeyShaped = (value) => /(?:^|[^A-Za-z0-9])(?:sk|pk|rk|ghp|xox[a-z])[-_][A-Za-z0-9]{8,}/.test(value);

// ------------------------------------------------------------------ the repro (nslow N2) and the unit-level answer table

test('nslow N2 (M2-1): an auto-mode Claude Code session never gets an open-ended host dialog for a hold (E2 froze 95 min)', () => {
  const guidance = ordinaryApprovalGuidance(normalizeRuntimeResult(hostRuntime('gate-nslow')));
  // Even with the owner's fresh prompt in the session, auto never asks.
  assert.equal(recordAttendedPrompt('n2-attended'), true);
  for (const event of [{ permission_mode: 'auto', scratchpad_dir: '/s' }, { permission_mode: 'auto' }, { permission_mode: 'auto', session_id: 'n2-attended' }, { permission_mode: 'auto', session_id: 'n2-attended', scratchpad_dir: '/s' }, { permission_mode: 'auto', session_id: 'any-session' }]) {
    const claudePrompt = ownerApprovalPrompt('claude-code', event, {});
    assert.equal(claudePrompt.available, false, JSON.stringify(event));
    const plan = planHeldAction({ guidance, host: 'claude-code', hookEvent: 'PreToolUse', reason: 'held', claudePrompt });
    assert.equal(plan.kind, 'deny');
    assert.equal(plan.agentText, M0_TEXT('gate-nslow'));
  }
});

