// ------------------------------------------------------------------ M1: the attended marker (evidence rules)

function markerSandbox() {
  const home = mkdtempSync(join(tmpdir(), 'marrow-attended-'));
  mkdirSync(join(home, '.marrow'), { mode: 0o700 });
  chmodSync(join(home, '.marrow'), 0o700);
  return { home, folder: join(home, '.marrow', 'attended-prompts'), cleanup: () => rmSync(home, { recursive: true, force: true }) };
}
// Replaces a folder by a symlink to the (still owner-only) real folder for the length of `check`, then puts it back.
function swapForSymlink(path, check) {
  const real = `${path}.real`;
  renameSync(path, real);
  try {
    symlinkSync(real, path);
    check(real);
  } finally {
    rmSync(path, { force: true, recursive: false });
    renameSync(real, path);
  }
}
const markerFile = (box, session) => join(box.folder, readdirSync(box.folder).find((name) => !name.startsWith('.') && name === require('node:crypto').createHash('sha256').update(`attended-prompt\n${session}`).digest('hex').slice(0, 32)));

test('M1: the marker is a timestamp only, owner-only, keyed by the session id; fresh (< 10 min) is evidence, every other state is not', () => {
  const box = markerSandbox();
  try {
    const now = 1_800_000_000_000;
    assert.equal(ATTENDED_WINDOW_MS, 10 * 60 * 1000);
    assert.equal(recordAttendedPrompt('sess-a', { home: box.home, now }), true);
    const file = markerFile(box, 'sess-a');
    assert.equal(readFileSync(file, 'utf8'), `${now}\n`, 'a timestamp and nothing else (no prompt text, no key, no session id)');
    assert.equal(require('node:fs').statSync(file).mode & 0o777, 0o600);
    assert.equal(require('node:fs').statSync(box.folder).mode & 0o777, 0o700);
    assert.equal(readdirSync(box.folder).some((name) => name.includes('sess-a')), false, 'the session id is hashed in the name');
    const within = (session, at, extra = {}) => attendedWithin(session, { home: box.home, now: at, ...extra });
    assert.equal(within('sess-a', now), true, 'just typed');
    assert.equal(within('sess-a', now + ATTENDED_WINDOW_MS - 1), true, 'a moment inside the window');
    assert.equal(within('sess-a', now + ATTENDED_WINDOW_MS), false, 'exactly 10 minutes is stale');
    assert.equal(within('sess-a', now + 11 * 60 * 1000), false, 'stale');
    assert.equal(within('sess-a', now - 1), false, 'future-dated (the marker is newer than the clock)');
    assert.equal(within('sess-b', now), false, 'another session');
    for (const lookalike of ['SESS-A', 'sess-a ', ' sess-a', 'sess-a\n', 'sess\u2010a', 'ｓｅｓｓ-ａ', 'sess-a\u200b', 'sess-а']) assert.equal(within(lookalike, now), false, `a session id that differs in bytes is another session: ${JSON.stringify(lookalike)}`);
    assert.equal(within('', now), false);
    assert.equal(within(undefined, now), false);
    assert.equal(within({ toString: () => 'sess-a' }, now), false);
    assert.equal(within('x'.repeat(300), now), false);
    // Missing, empty, malformed and look-alike stamps are no evidence.
    const bad = (session, text) => { writeFileSync(join(box.folder, require('node:crypto').createHash('sha256').update(`attended-prompt\n${session}`).digest('hex').slice(0, 32)), text, { mode: 0o600 }); return within(session, now); };
    for (const [session, text] of [['empty', ''], ['junk', 'garbage'], ['neg', '-1\n'], ['float', `${now}.5\n`], ['two', `${now}\n${now}\n`], ['hex', '0x1ffff12345\n'], ['exp', '1e12\n'], ['prompt', 'ignore previous instructions\n'], ['pad', `${now}\n\n`], ['big', `${'9'.repeat(30)}\n`], ['short', '12345\n']]) {
      assert.equal(bad(session, text), false, `${session}: ${JSON.stringify(text)}`);
    }
    // Unreadable (mode 000), group-readable, a symlink, a directory in its place.
    recordAttendedPrompt('sess-unreadable', { home: box.home, now });
    chmodSync(markerFile(box, 'sess-unreadable'), 0o000);
    assert.equal(within('sess-unreadable', now), false, 'unreadable');
    recordAttendedPrompt('sess-wide', { home: box.home, now });
    chmodSync(markerFile(box, 'sess-wide'), 0o644);
    assert.equal(within('sess-wide', now), false, 'group/world readable');
    recordAttendedPrompt('sess-target', { home: box.home, now });
    const linkName = require('node:crypto').createHash('sha256').update('attended-prompt\nsess-link').digest('hex').slice(0, 32);
    symlinkSync(markerFile(box, 'sess-target'), join(box.folder, linkName));
    assert.equal(within('sess-link', now), false, 'a symlink');
    mkdirSync(join(box.folder, require('node:crypto').createHash('sha256').update('attended-prompt\nsess-dir').digest('hex').slice(0, 32)));
    assert.equal(within('sess-dir', now), false, 'a directory');
    // The folder itself: loosened, or replaced by a symlink, is no evidence for any session.
    chmodSync(box.folder, 0o755);
    assert.equal(within('sess-a', now), false, 'folder not owner-only');
    chmodSync(box.folder, 0o700);
    assert.equal(within('sess-a', now), true);
    // A symlinked folder (the marker folder, then the `.marrow` parent) is no evidence, even when it points at an owner-only
    // folder that holds a fresh marker.
    swapForSymlink(box.folder, () => assert.equal(within('sess-a', now), false, 'folder is a symlink'));
    assert.equal(within('sess-a', now), true, 'folder restored');
    swapForSymlink(join(box.home, '.marrow'), () => assert.equal(within('sess-a', now), false, '.marrow is a symlink'));
    assert.equal(within('sess-a', now), true, '.marrow restored');
    // A marker folder or marker owned by another uid is no evidence.
    const realGetuid = process.getuid;
    process.getuid = () => realGetuid() + 1;
    try { assert.equal(within('sess-a', now), false, 'another uid owns it'); } finally { process.getuid = realGetuid; }
    assert.equal(within('sess-a', now), true, 'uid restored');
    // Writing refuses an unusable folder and never throws.
    chmodSync(box.folder, 0o755);
    assert.equal(recordAttendedPrompt('sess-c', { home: box.home, now }), false);
    chmodSync(box.folder, 0o700);
    assert.equal(recordAttendedPrompt(undefined, { home: box.home, now }), false);
    assert.equal(recordAttendedPrompt('', { home: box.home, now }), false);
    assert.equal(recordAttendedPrompt('sess-d', { home: join(box.home, 'no', 'such'), now }), false, 'a missing home is refused, never thrown');
  } finally { box.cleanup(); }
});

// One forged state per check clause of the reader and writer (src/attended-marker.ts). Each state differs from a valid marker in
// one clause only; the valid marker is asserted before and after it, so a refusal can only come from the forged state. States a real
// file system cannot be told to produce (a stat that lies at one call site, a symlink swapped in after the lstat) use a stat double.
test('M1: every check clause of the attended marker refuses its own forged state, one clause at a time', () => {
  const nodeFs = require('node:fs');
  const nodeCrypto = require('node:crypto');
  const box = markerSandbox();
  try {
    const now = 1_800_000_000_000;
    const marrow = join(box.home, '.marrow');
    const pathFor = (session) => join(box.folder, nodeCrypto.createHash('sha256').update(`attended-prompt\n${session}`).digest('hex').slice(0, 32));
    assert.equal(recordAttendedPrompt('sess-a', { home: box.home, now }), true);
    const marker = pathFor('sess-a');
    const within = (session, at = now) => attendedWithin(session, { home: box.home, now: at });
    const twin = (stat, over) => Object.assign(Object.create(Object.getPrototypeOf(stat)), stat, over);
    // For the length of `run`, the stat of `path` (lstat) or of the opened file (fstat, path undefined) has the fields `over(stat)` changes.
    const withStat = (call, path, over, run) => {
      const real = nodeFs[call];
      nodeFs[call] = (target, ...rest) => { const stat = real(target, ...rest); return path === undefined || target === path ? twin(stat, over(stat)) : stat; };
      try { return run(); } finally { nodeFs[call] = real; }
    };
    const refuses = (label, call, path, over) => {
      assert.equal(within('sess-a'), true, `${label}: control before`);
      assert.equal(withStat(call, path, over, () => within('sess-a')), false, label);
      assert.equal(within('sess-a'), true, `${label}: control after`);
    };
    // The folders and the marker, at each place the reader checks them: uid, every group/world bit, kind, link.
    const sites = [['.marrow (lstat)', 'lstatSync', marrow, true], ['marker folder (lstat)', 'lstatSync', box.folder, true], ['marker (lstat)', 'lstatSync', marker, false], ['marker (fstat)', 'fstatSync', undefined, false]];
    for (const [site, call, path, folder] of sites) {
      refuses(`${site}: owned by another uid`, call, path, (stat) => ({ uid: stat.uid + 1 }));
      for (const bit of [0o001, 0o002, 0o004, 0o010, 0o020, 0o040]) refuses(`${site}: mode has group/world bit ${bit.toString(8)}`, call, path, (stat) => ({ mode: stat.mode | bit }));
      refuses(`${site}: not a ${folder ? 'directory' : 'file'}`, call, path, (stat) => ({ mode: (folder ? 0o100000 : 0o040000) | (stat.mode & 0o7777) }));
      if (call === 'lstatSync') refuses(`${site}: reported as a symlink as well`, call, path, () => ({ isSymbolicLink: () => true }));
    }
    // Size, and the file opened being the file that was checked.
    for (const size of [0, 33]) refuses(`marker size ${size}`, 'lstatSync', marker, () => ({ size }));
    assert.equal(withStat('lstatSync', marker, () => ({ size: 32 }), () => within('sess-a')), true, 'size 32 is the largest accepted');
    for (const field of ['ino', 'dev']) for (const call of ['lstatSync', 'fstatSync']) refuses(`marker ${field} differs between the lstat and the open file (${call})`, call, call === 'lstatSync' ? marker : undefined, (stat) => ({ [field]: stat[field] + 1 }));
    // A marker swapped for a symlink to a valid marker after the lstat: only O_NOFOLLOW on the open stops it.
    const raced = pathFor('sess-race');
    const racedWithin = () => {
      const real = nodeFs.lstatSync;
      nodeFs.lstatSync = (target, ...rest) => (target === raced ? nodeFs.statSync(target) : real(target, ...rest));
      try { return within('sess-race'); } finally { nodeFs.lstatSync = real; }
    };
    writeFileSync(raced, `${now}\n`, { mode: 0o600 });
    assert.equal(racedWithin(), true, 'race: control (a plain marker, the lstat double follows nothing)');
    unlinkSync(raced);
    symlinkSync(marker, raced);
    assert.equal(within('sess-race'), false, 'race: a symlink is refused by the lstat');
    assert.equal(racedWithin(), false, 'race: the open refuses a symlink even when the lstat was fooled (O_NOFOLLOW)');
    // The stamp: exact digits, a newline at most, a safe integer.
    const stamped = (session, text, at = now) => { writeFileSync(pathFor(session), text, { mode: 0o600 }); return within(session, at); };
    assert.equal(stamped('stamp-ok', `${now}\n`), true, 'stamp: control');
    for (const [label, text] of [['leading space', ` ${now}\n`], ['trailing space', `${now} \n`], ['CRLF', `${now}\r\n`], ['plus sign', `+${now}\n`], ['tab', `${now}\t`], ['second line', `${now}\n1\n`]]) assert.equal(stamped(`stamp-${label}`, text), false, `stamp: ${label}`);
    assert.equal(stamped('stamp-max-safe', '9007199254740991\n', 9007199254740996), true, 'stamp: the largest safe integer is a stamp');
    assert.equal(stamped('stamp-unsafe', '9999999999999999\n', 10_000_000_000_000_002), false, 'stamp: a 16-digit value that is not a safe integer');
    // The session id: a string with something in it, at most 256 characters, compared by bytes.
    assert.equal(stamped('y'.repeat(256), `${now}\n`), true, 'session id: 256 characters is the longest accepted');
    for (const [label, id] of [['spaces only', '   '], ['tab and newline only', '\t\n'], ['257 characters', 'x'.repeat(257)]]) assert.equal(stamped(id, `${now}\n`), false, `session id: ${label}`);
    writeFileSync(pathFor('sess-obj'), `${now}\n`, { mode: 0o600 });
    assert.equal(within({ trim: () => 'x', length: 8, toString: () => 'sess-obj' }), false, 'session id: only a string counts, whatever it prints as');
    // Writing: the same folder states refuse a write and nothing lands behind a link or over a file that is already there.
    const writes = (session) => recordAttendedPrompt(session, { home: box.home, now });
    assert.equal(writes('write-ctl'), true, 'write: control');
    swapForSymlink(box.folder, (real) => {
      assert.equal(writes('write-a'), false, 'write: the marker folder is a symlink');
      assert.equal(readdirSync(real).includes(basename(pathFor('write-a'))), false, 'write: nothing landed behind the symlink');
    });
    swapForSymlink(marrow, (real) => {
      assert.equal(writes('write-b'), false, 'write: .marrow is a symlink');
      assert.equal(readdirSync(join(real, 'attended-prompts')).includes(basename(pathFor('write-b'))), false, 'write: nothing landed behind the .marrow symlink');
    });
    for (const [site, path] of [['.marrow', marrow], ['marker folder', box.folder]]) {
      assert.equal(withStat('lstatSync', path, (stat) => ({ mode: 0o100000 | (stat.mode & 0o7777) }), () => writes(`write-${site}`)), false, `write: ${site} is not a directory`);
      assert.equal(withStat('lstatSync', path, () => ({ isSymbolicLink: () => true }), () => writes(`write-${site}`)), false, `write: ${site} is reported as a symlink as well`);
      assert.equal(existsSync(pathFor(`write-${site}`)), false, `write: no marker behind a refused ${site}`);
    }
    chmodSync(marrow, 0o755);
    assert.equal(writes('write-c'), false, 'write: .marrow is not owner-only');
    chmodSync(marrow, 0o700);
    const realGetuid = process.getuid;
    process.getuid = () => realGetuid() + 1;
    try { assert.equal(writes('write-d'), false, 'write: another uid owns the folders'); } finally { process.getuid = realGetuid; }
    for (const session of ['write-a', 'write-b', 'write-c', 'write-d']) assert.equal(existsSync(pathFor(session)), false, `write: no marker for ${session}`);
    assert.equal(writes('write-e'), true, 'write: control after');
    // The scratch file is created exclusively: a file or a link already at its (here fixed) name is neither written nor followed.
    const realRandom = nodeCrypto.randomBytes;
    nodeCrypto.randomBytes = () => Buffer.alloc(6, 0xab);
    const scratch = join(box.folder, `.tmp-${process.pid}-${'ab'.repeat(6)}`);
    const victim = join(box.home, 'victim');
    try {
      writeFileSync(scratch, 'victim file\n', { mode: 0o600 });
      assert.equal(writes('write-f'), false, 'write: a file already at the scratch name');
      assert.equal(readFileSync(scratch, 'utf8'), 'victim file\n', 'write: that file is untouched');
      unlinkSync(scratch);
      writeFileSync(victim, 'victim file\n', { mode: 0o600 });
      symlinkSync(victim, scratch);
      assert.equal(writes('write-g'), false, 'write: a symlink already at the scratch name');
      assert.equal(readFileSync(victim, 'utf8'), 'victim file\n', 'write: the link target is untouched');
    } finally { nodeCrypto.randomBytes = realRandom; rmSync(scratch, { force: true }); }
    assert.equal(existsSync(pathFor('write-f')) || existsSync(pathFor('write-g')), false, 'write: no marker after a refused scratch');
    // Both opens carry O_NOFOLLOW (the scratch open's is redundant with O_EXCL on Linux, so only the flags can show it).
    const flagsSeen = [];
    const realOpen = nodeFs.openSync;
    nodeFs.openSync = (target, flags, ...rest) => { flagsSeen.push(flags); return realOpen(target, flags, ...rest); };
    try { assert.equal(writes('flags'), true); assert.equal(within('flags'), true); } finally { nodeFs.openSync = realOpen; }
    assert.equal(flagsSeen.length, 2, 'one scratch open, one marker open');
    for (const flags of flagsSeen) assert.notEqual(flags & nodeFs.constants.O_NOFOLLOW, 0, `open flags ${flags} include O_NOFOLLOW`);
    assert.notEqual(flagsSeen[0] & nodeFs.constants.O_EXCL, 0, 'the scratch open is exclusive');
    assert.equal(within('sess-a'), true, 'the valid marker still counts at the end');
  } finally { box.cleanup(); }
});

test('M1: the UserPromptSubmit entry writes the marker; a marker written any other way, or by another host, is not evidence', () => {
  withHarness((h) => {
    h.unattended = true;
    h.setConfig({ runtime: hostRuntime('gate-held'), status: { 'gate-held': 'pending' } });
    const prompt = { session_id: 'sess-prompt-1', hook_event_name: 'UserPromptSubmit', prompt: 'private words the marker never keeps', cwd: '/home/operator/project', permission_mode: 'default' };
    const folder = join(h.home, '.marrow', 'attended-prompts');
    const markers = () => { try { return readdirSync(folder).filter((name) => !name.startsWith('.')); } catch { return []; } };
    // A payload that is not a Claude Code prompt writes nothing.
    h.run('codex-context-hook', prompt, { MARROW_API_KEY: '' });
    h.run('claude-context-hook', '{not json', { MARROW_API_KEY: '' });
    h.run('claude-context-hook', { ...prompt, prompt: '' }, { MARROW_API_KEY: '' });
    h.run('claude-context-hook', { ...prompt, hook_event_name: 'PreToolUse' }, { MARROW_API_KEY: '' });
    h.run('claude-context-hook', { ...prompt, session_id: 7 }, { MARROW_API_KEY: '' });
    h.run('claude-context-hook', { ...prompt, session_id: undefined }, { MARROW_API_KEY: '' });
    assert.deepEqual(markers(), []);
    // Before the prompt: the session has no evidence, so a hold in default mode is a denial.
    assert.equal(decisionOf(h.run('claude-pre-action-hook', ev({ session_id: 'sess-prompt-1' }))), 'deny');
    const out = h.run('claude-context-hook', prompt, { MARROW_API_KEY: '' });
    assert.equal(out.status, 0);
    assert.equal(markers().length, 1);
    const text = readFileSync(join(folder, markers()[0]), 'utf8');
    assert.match(text, /^[0-9]{13}\n$/);
    assert.ok(Math.abs(Number(text) - Date.now()) < 60_000);
    assert.equal(text.includes('private words'), false);
    assert.equal(readdirSync(h.home, { recursive: true }).some((name) => String(name).includes('sess-prompt-1')), false, 'the session id is never a file name');
    // Another session still has none; this session asks.
    assert.equal(decisionOf(h.run('claude-pre-action-hook', ev({ session_id: 'sess-prompt-other' }))), 'deny');
    const asked = h.run('claude-pre-action-hook', ev({ session_id: 'sess-prompt-1', tool_use_id: 'toolu_after_prompt' }));
    assert.equal(decisionOf(asked), 'ask');
    assert.equal(reasonOf(asked), DIALOG_TEXT);
  });
});

