const CONTROL_OFF = 'npx @getmarrow/install control disable --yes';

test('M2-7 (A39) + M1: control off is the owner-terminal denial in auto and in default without evidence, never an ask; an attended default session keeps the master flow', () => {
  withHeld((h) => {
    h.unattended = true;
    for (const [label, over] of [['auto', { permission_mode: 'auto' }], ['bypassPermissions', { permission_mode: 'bypassPermissions' }], ['dontAsk', { permission_mode: 'dontAsk' }], ['default, no evidence', { permission_mode: 'default' }], ['acceptEdits, no evidence', { permission_mode: 'acceptEdits' }]]) {
      const out = h.run('claude-pre-action-hook', ev({ ...over, tool_input: { command: CONTROL_OFF }, tool_use_id: `toolu_r8_${label.replace(/\W/g, '')}` }));
      assert.equal(decisionOf(out), 'deny', label);
      assert.equal(reasonOf(out), CONTROL_ROUTE_DENY_TEXT, label);
      assert.equal(asks(out), false, label);
    }
    assert.equal(runtimeCalls(h).length, 0, 'the owner-terminal denial is local: nothing reached the backend');
    assert.doesNotMatch(CONTROL_ROUTE_DENY_TEXT, /npx|install|disable|--yes|marrow-install/i, 'the text carries no runnable control-off or identity command');
    h.unattended = false;
    const attended = h.run('claude-pre-action-hook', ev({ permission_mode: 'default', tool_input: { command: CONTROL_OFF }, tool_use_id: 'toolu_r8_attended' }));
    assert.notEqual(reasonOf(attended), M0_TEXT('gate-t'));
    assert.ok(['ask', 'deny'].includes(decisionOf(attended)), attended.stdout);
    assert.equal(runtimeCalls(h).length >= 1, true, 'with a person at the prompt the call goes to the backend as on master');
  });
});

test('M4 shortcut cross rows: the auto deny never hides a stricter answer, and a fresh marker never turns a master denial into an ask', () => {
  // P1 control off (above), P2 production deploy and publish, P3 secret read, P4 persistence, P5 backend block / owner-locked / arbitration.
  const CASES = [
    ['P2 deploy', 'wrangler deploy --env production', 'hold'],
    ['P2 publish', 'npm publish', 'hold'],
    ['P3 secret read', 'cat ~/.aws/credentials', 'hold'],
    ['P4 persistence', "printf 'x' >> ~/.bashrc", 'hold'],
    ['P4 hooks settings', "printf '{}' >> ~/.claude/settings.json", 'hold'],
  ];
  for (const [label, command, kind] of CASES) {
    for (const [mode, expected] of [['auto', 'deny'], ['default+unattended', 'deny'], ['default+attended', 'ask'], ['bypassPermissions', 'deny'], ['dontAsk', 'deny'], ['plan', 'deny']]) {
      withHeld((h) => {
        h.unattended = mode === 'default+unattended';
        const out = h.run('claude-pre-action-hook', ev({ permission_mode: mode.split('+')[0], tool_input: { command } }));
        assert.ok(['ask', 'deny'].includes(decisionOf(out)), `${label} ${mode}: ${out.stdout.slice(0, 200)}`);
        assert.equal(decisionOf(out), expected, `${label} ${mode}`);
        if (mode === 'auto' || mode === 'default+unattended') assert.equal(reasonOf(out), M0_TEXT('gate-t'), `${label} ${mode}`);
      });
    }
  }
  // Backend denials stay denials with their own text, with and without a fresh marker.
  const block = hostRuntime('gate-blocked', {}, { risk_gate: { allow: false, decision: 'block', enforced: true, gate_required: true, gate_receipt_id: 'gate-blocked', risk_level: 'high', reasons: [{ message: 'Release freeze is active.' }] }, gate_receipt: { id: 'gate-blocked', decision: 'block', required: true } });
  const arbitration = hostRuntime('gate-arb', {}, { arbitration: { receipt_id: 'arb-1', resolution: 'review_required' } });
  for (const [label, runtime, pattern] of [['block', block, /^Marrow blocked this action under the current policy\. Reason: Release freeze is active\.$/], ['arbitration', arbitration, /^Marrow is holding this action for arbitration review/], ['owner-locked', ownerLockedRuntime('gate-t'), /The account owner approves production_deploy actions personally/]]) {
    for (const [mode, attended] of [['auto', false], ['default', true], ['default', false], ['acceptEdits', true]]) {
      withHeld((h) => {
        h.unattended = !attended;
        const out = h.run('claude-pre-action-hook', ev({ permission_mode: mode }));
        assert.equal(decisionOf(out), 'deny', `${label} ${mode} attended=${attended}`);
        assert.match(reasonOf(out), pattern, `${label} ${mode} attended=${attended}`);
        assert.notEqual(reasonOf(out), M0_TEXT('gate-t'));
      }, runtime);
    }
  }
});

test('M1/M4: a marker written through an agent tool is itself a held security write on the self-protected ~/.marrow (no forged evidence by file)', () => {
  const home = process.env.HOME;
  for (const event of [
    { tool_name: 'Bash', tool_input: { command: 'printf 1800000000000 > ~/.marrow/attended-prompts/abc' } },
    { tool_name: 'Bash', tool_input: { command: 'echo $(date +%s%3N) | tee $HOME/.marrow/attended-prompts/abc' } },
    { tool_name: 'Bash', tool_input: { command: `cp /dev/null ${home}/.marrow/attended-prompts/abc` } },
    { tool_name: 'Write', tool_input: { file_path: `${home}/.marrow/attended-prompts/abc`, content: '1800000000000\n' } },
    { tool_name: 'Edit', tool_input: { file_path: `${home}/.marrow/attended-prompts/abc`, old_string: 'a', new_string: 'b' } },
  ]) {
    const classified = classifyTool({ ...event, cwd: '/work' });
    assert.equal(classified.protected, true, JSON.stringify(event));
    assert.equal(classified.type, 'security', JSON.stringify(event));
    assert.ok(classified.surfaces.includes('marrow-control'), JSON.stringify(event));
  }
});

