const BASE_TABLE = JSON.parse(readFileSync(join(__dirname, 'fixtures', 'no-freeze-holds', 'base-hold-plans.json'), 'utf8'));

test('M6/M2-5: every other host and every unchanged Claude Code mode answers exactly as master (the committed BASE table)', () => {
  const home = mkdtempSync(join(tmpdir(), 'marrow-plan-table-home-'));
  const previous = process.env.HOME;
  process.env.HOME = home;
  try {
    mkdirSync(join(home, '.marrow'), { mode: 0o700 });
    const candidate = buildTable(join(__dirname, '..', 'dist'), { hostRuntime });
    assert.deepEqual(Object.keys(candidate.claude), Object.keys(BASE_TABLE.claude));
    assert.deepEqual(candidate.others, BASE_TABLE.others, 'Cursor, Codex, Gemini, Grok, Cline and Windsurf: every plan in every combination equals master (and ignores the new claudePrompt field)');
    const changed = [];
    for (const [key, base] of Object.entries(BASE_TABLE.claude)) {
      const row = candidate.claude[key];
      const [, variant, kind] = key.split('|');
      const ordinary = kind === 'ordinary' || kind === 'ordinary_ping';
      const mustChange = ordinary && (variant.startsWith('auto') || variant.endsWith('+unattended'));
      if (!mustChange) {
        assert.deepEqual(row.plan, base.plan, `${key}: unchanged from master`);
        if (!variant.startsWith('auto') && !variant.endsWith('+unattended')) assert.deepEqual(row.prompt, base.prompt, key);
        continue;
      }
      changed.push(`${key}: ${base.plan.kind} -> ${row.plan.kind}`);
      assert.equal(row.plan.kind, 'deny', key);
      assert.equal(row.prompt.available, false, key);
      assert.ok(base.plan.kind === 'ask' || base.plan.kind === 'deny', key);
      assert.equal(row.plan.agentText.startsWith(M0_TEXT('gate-t')), true, key);
      assert.equal(row.plan.agentText.slice(M0_TEXT('gate-t').length), kind === 'ordinary_ping' ? ' [owner-request]' : '', key);
      assert.equal(row.plan.dialogLater, true, key);
      assert.equal(row.plan.ownerLink, kind === 'ordinary_ping' ? 'now' : undefined, key);
      assert.equal(row.plan.quiet, undefined, key);
      assert.equal(row.plan.code, false, key);
    }
    // Never looser: a master denial is still a denial; a master ask is an ask or a denial; nothing becomes allow or pass.
    for (const [key, base] of Object.entries(BASE_TABLE.claude)) {
      const now = candidate.claude[key].plan.kind;
      assert.ok(now === 'deny' || (now === 'ask' && base.plan.kind === 'ask'), `${key}: ${base.plan.kind} -> ${now}`);
    }
    assert.equal(changed.length, 10, changed.join('\n'));
    // The changed Claude Code rows, by mode (the table in the result).
    const byMode = (variant) => changed.filter((line) => line.startsWith(`claude-code|${variant}|`)).length;
    for (const variant of ['default+unattended', 'acceptEdits+unattended', 'auto+scratchpad', 'auto+no-scratchpad', 'auto+unattended']) assert.equal(byMode(variant), 2, variant);
    for (const variant of Object.keys(CLAUDE_VARIANTS)) {
      if (variant.startsWith('auto') || variant.endsWith('+unattended')) continue;
      assert.equal(byMode(variant), 0, `${variant} is unchanged`);
    }
  } finally {
    if (previous === undefined) delete process.env.HOME; else process.env.HOME = previous;
    rmSync(home, { recursive: true, force: true });
  }
});

// ------------------------------------------------------------------ M0, M4: scope and text gates

test('M0/M4: the new texts carry the receipt and no runnable command; the dummy keys are not live-shaped', () => {
  for (const text of [M0_TEXT('gate-x'), heldNoFreezeText('gate-x'), CONTROL_ROUTE_DENY_TEXT]) {
    assert.doesNotMatch(text, /npx|npm |marrow-install|@getmarrow|control disable|--yes|\$\(|`/i, text);
  }
  assert.equal(heldNoFreezeText('gate-x'), M0_TEXT('gate-x'));
  assert.doesNotMatch(heldNoFreezeText('gate-x'), /queue/i, 'no queue is claimed');
  for (const hex of Array.from({ length: 50 }, () => require('node:crypto').randomBytes(16).toString('hex'))) assert.equal(dummyKeyShaped(`nslowdummy_${hex}`), false);
  const text = readFileSync(join(__dirname, '..', 'src', 'host-approval.ts'), 'utf8') + readFileSync(join(__dirname, '..', 'src', 'attended-marker.ts'), 'utf8');
  assert.doesNotMatch(text, /sk_live|pk_live|ghp_[A-Za-z0-9]{20}/);
});

test('M1: the three ask emitters share one source (the attended check lives in ownerApprovalPrompt)', () => {
  const source = readFileSync(join(__dirname, '..', 'src', 'hook-pre-action.ts'), 'utf8');
  assert.equal((source.match(/attendedWithin\(/g) || []).length, 1, 'one attended check');
  assert.match(source, /export function ownerApprovalPrompt[\s\S]*?attendedWithin\(event\.session_id\)/);
  // planHeldAction (claudePrompt), resumeWaitingHold (dialogAvailable) and the legacy ask (prompt.available) all take it from there.
  assert.match(source, /const dialogAvailable = holdContext\.host === 'claude-code' && ownerApprovalPrompt\(identity\.harness, source\)\.available/);
  assert.match(source, /const claudePrompt = ownerApprovalPrompt\(identity\.harness, source\)/);
  assert.equal((source.match(/permissionDecision: 'ask'/g) || []).length, 2, 'the legacy ask and the held-action ask are the only ask outputs of this file');
  assert.equal(classifyTool({ tool_name: 'Bash', tool_input: { command: 'ls' } }).readOnly, true);
});
